ass="card-actions"><a class="btn btn-primary" href="product.php?id=<?=e($p['id'])?>">বিস্তারিত</a><a class="btn btn-secondary" href="cart.php?add=<?=e($p['id'])?>">কার্টে যোগ</a></div></div></article><?php endforeach;?></div></section></main><footer class="site-footer"><h2><?=e(siteName())?></h2><p><?=e(setting('footer_description','আপনার গ্যাজেট শপ'))?></p><div class="footer-meta"><span>☎ <?=e(setting('phone',''))?></span><span>✉ <?=e(setting('email',''))?></span><span>📍 <?=e(setting('address',''))?></span></div></footer><script>document.querySelector('.hamburger-btn')?.addEventListener('click',()=>document.getElementById('mainNav').classList.toggle('open'));</script></body></html>
